WITH lines AS (SELECT id, host, level, latency_ms, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) li AS k, attr_value) SELECT host, CASE WHEN latency_ms >= 2402 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN level = 'WARN' THEN 1 END), 0), 2) AS latency_ms_per_warn, PERCENTILE_APPROX(latency_ms, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_quartiles FROM lines GROUP BY host, CASE WHEN latency_ms >= 2402 THEN 'PREMIUM' ELSE 'STANDARD' END
